<?php
/* ============================================================================
   SHADOWX STUDIOS — IMAGE UPLOADS
   ----------------------------------------------------------------------------
   Files land in /uploads. Security rules applied here:

     * the real image type is read from the file's own bytes (getimagesize),
       not from the filename or the browser-supplied content-type
     * only jpg / png / webp / gif are accepted
     * the stored filename is generated by us, never taken from the upload
     * .htaccess inside /uploads blocks PHP execution, so even if something
       nasty got written there it cannot be run

   Large images are automatically resized down to 1600px and re-encoded, which
   both strips any embedded junk and keeps the site fast.
   ========================================================================== */

require_once __DIR__ . '/config.php';
require_once __DIR__ . '/projects.php';

const UPLOAD_MAX_EDGE = 1600;

/**
 * Handle one $_FILES entry.
 * Returns ['ok'=>true,'src'=>'uploads/name.webp'] or ['ok'=>false,'error'=>'…'].
 */
function sx_handle_upload(array $file, string $slugHint = 'image'): array
{
    $fail = fn(string $m) => ['ok' => false, 'error' => $m];

    if (!isset($file['error']) || is_array($file['error'])) {
        return $fail('Malformed upload.');
    }
    switch ($file['error']) {
        case UPLOAD_ERR_OK:
            break;
        case UPLOAD_ERR_NO_FILE:
            return $fail('No file was chosen.');
        case UPLOAD_ERR_INI_SIZE:
        case UPLOAD_ERR_FORM_SIZE:
            return $fail('That file is larger than the server allows.');
        default:
            return $fail('Upload failed (code ' . (int)$file['error'] . ').');
    }

    if (($file['size'] ?? 0) > MAX_UPLOAD_BYTES) {
        return $fail('Image must be under ' . round(MAX_UPLOAD_BYTES / 1048576) . ' MB.');
    }
    if (!is_uploaded_file($file['tmp_name'])) {
        return $fail('Upload could not be verified.');
    }

    // Identify by content, not by name.
    $info = @getimagesize($file['tmp_name']);
    if ($info === false || !isset($info[2]) || !isset(ALLOWED_IMAGE_TYPES[$info[2]])) {
        return $fail('That file is not a JPG, PNG, WEBP or GIF image.');
    }
    $type = $info[2];
    $ext  = ALLOWED_IMAGE_TYPES[$type];

    if (!is_dir(SX_UPLOADS) && !@mkdir(SX_UPLOADS, 0755, true)) {
        return $fail('The uploads folder could not be created.');
    }
    if (!is_writable(SX_UPLOADS)) {
        return $fail('The uploads folder is not writable. Set it to 755 in your file manager.');
    }

    $name = sx_slug($slugHint) . '-' . bin2hex(random_bytes(5)) . '.' . $ext;
    $dest = SX_UPLOADS . '/' . $name;

    // Re-encode when GD is available: resizes, and discards anything that is
    // not actually image data.
    $done = false;
    if (function_exists('imagecreatefromstring')) {
        $done = sx_reencode($file['tmp_name'], $dest, $type);
    }
    if (!$done && !move_uploaded_file($file['tmp_name'], $dest)) {
        return $fail('Could not save the uploaded file.');
    }

    @chmod($dest, 0644);
    return ['ok' => true, 'src' => 'uploads/' . $name];
}

function sx_reencode(string $src, string $dest, int $type): bool
{
    $raw = @file_get_contents($src);
    if ($raw === false) { return false; }
    $im = @imagecreatefromstring($raw);
    if ($im === false) { return false; }

    $w = imagesx($im);
    $h = imagesy($im);
    $max = max($w, $h);

    if ($max > UPLOAD_MAX_EDGE) {
        $scale = UPLOAD_MAX_EDGE / $max;
        $nw = max(1, (int)round($w * $scale));
        $nh = max(1, (int)round($h * $scale));
        $out = imagecreatetruecolor($nw, $nh);
        imagealphablending($out, false);
        imagesavealpha($out, true);
        imagecopyresampled($out, $im, 0, 0, 0, 0, $nw, $nh, $w, $h);
        imagedestroy($im);
        $im = $out;
    }

    $ok = false;
    switch ($type) {
        case IMAGETYPE_JPEG: $ok = imagejpeg($im, $dest, 82);  break;
        case IMAGETYPE_PNG:  $ok = imagepng($im, $dest, 6);    break;
        case IMAGETYPE_WEBP: $ok = function_exists('imagewebp') && imagewebp($im, $dest, 82); break;
        case IMAGETYPE_GIF:  $ok = imagegif($im, $dest);       break;
    }
    imagedestroy($im);
    return $ok;
}

/**
 * Delete an uploaded image. Only ever touches files inside /uploads, and
 * never the three original project images that ship with the site.
 */
function sx_delete_upload(string $src): bool
{
    if (strpos($src, 'uploads/') !== 0) {
        return false;                       // not ours to delete
    }
    $name = basename($src);
    $path = SX_UPLOADS . '/' . $name;
    $real = realpath($path);
    $base = realpath(SX_UPLOADS);
    if ($real === false || $base === false || strpos($real, $base) !== 0) {
        return false;                       // path traversal attempt
    }
    return @unlink($real);
}

/** True if this image is referenced by any project other than $exceptId. */
function sx_image_in_use(string $src, string $exceptId = ''): bool
{
    foreach (sx_load_projects() as $p) {
        if (($p['id'] ?? '') === $exceptId) { continue; }
        foreach ($p['images'] ?? [] as $img) {
            if (($img['src'] ?? '') === $src) { return true; }
        }
    }
    return false;
}
